INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", "vo_minigame_1013", "", "vo_minigame_1013_top_talk_6_001", "", 6010, "", 21, 0, 0);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, 0.8, 129911, 0, "マコトさん？\nどうかしましたか？\n何やら不穏な気配を\n感じ取ったのですが", 0, 6011, 0, 11, 1, 6);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", 0, "", "", "", 6012, "", 91, "", "");
