INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", 129811, 0.2, "drama_talk_surprise_in_shy", "", 6014, 1, 3, "drama_talk_surprise_loop_shy", 0);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", "vo_minigame_1013", "", "vo_minigame_1013_top_talk_6_002", "", 6015, "", 21, 0, 0);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, 0.3, 129811, 0, "いやいや何でもない！\nあたしは別に変なこと\n考えてないからな！\nそれより訓練だっ！", 0, 6016, 0, 11, 1, 9);
INSERT INTO `v1_11e72e4ca9f08373164380d7c5b847f48af778235de3a7fe275d57b40c0161d0` VALUES (6, "", 0, "", "", "", 6017, "", 91, "", "");
